import{characters,games,STORAGE_KEY,blankState,pointsFor,leaderboard,award,validateBackup}from'./games.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=blankState(),loadError=false;
try{const saved=localStorage.getItem(STORAGE_KEY);if(saved)state=validateBackup(JSON.parse(saved));}catch{loadError=true;}
let activeGame=null,remaining=0,deadline=null,timerHandle=null,toastHandle=null,photoDraft=null;
const dialog=$('#main-dialog');
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastHandle);toastHandle=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{notify('Browser storage is full or unavailable. Download a backup to keep your changes.');}}
function avatar(p,extra=''){return p.photo?`<img class="avatar ${extra}" src="${escape(p.photo)}" alt="" loading="lazy">`:`<span class="avatar face-${p.avatar} ${extra}" aria-hidden="true"></span>`;}
function openModal(html,game=false){stopTimer();activeGame=null;dialog.classList.toggle('game-dialog',game);$('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');}
function closeModal(){stopTimer();activeGame=null;dialog.close();document.body.classList.remove('modal-open');render();}
$('#close-dialog').addEventListener('click',closeModal);dialog.addEventListener('cancel',e=>{e.preventDefault();closeModal();});
function render(){
 $('#games-grid').innerHTML=games.map((g,i)=>{const progress=state.progress[g.id]?.index||0;return`<article class="game-card"><div class="game-visual visual-${g.id}"><span class="game-number">0${i+1}</span><span class="game-label">${g.label}</span><span class="spark a" aria-hidden="true">✧</span><span class="game-icon ${g.id==='emoji'?'double':''}" aria-hidden="true">${g.icon}</span><span class="spark b" aria-hidden="true">✦</span></div><div class="game-info"><p class="game-meta">${g.minutes} &nbsp;·&nbsp; ${g.cards.length} ${g.id==='quiz'?'questions':g.id==='emoji'?'clues':'challenges'}</p><h3>${g.name}</h3><p>${g.description}</p><button class="card-start" data-game="${g.id}">${progress>=g.cards.length?'Round complete · view':progress>0?'Continue round':'Play this round'}<span aria-hidden="true">↗</span></button></div></article>`;}).join('');
 $$('[data-game]').forEach(b=>b.addEventListener('click',()=>launch(b.dataset.game)));
 $('#players-grid').innerHTML=state.players.length?state.players.map(p=>`<button class="player-card" data-player="${escape(p.id)}" aria-label="Edit ${escape(p.name)}">${avatar(p)}<h3>${escape(p.name)}</h3><p>${escape(p.nickname||characters[p.avatar].name)}</p></button>`).join(''):characters.map((c,i)=>`<button class="player-card" data-preset="${i}" aria-label="Add a player as ${escape(c.name)}"><span class="avatar face-${i}" aria-hidden="true"></span><h3>${c.name}</h3><p>${c.tag}</p><div class="example-label">Choose this character +</div></button>`).join('');
 $$('[data-player]').forEach(b=>b.addEventListener('click',()=>editPlayer(b.dataset.player)));$$('[data-preset]').forEach(b=>b.addEventListener('click',()=>editPlayer(null,Number(b.dataset.preset))));
 const ranked=leaderboard(state);let lastScore=null,rank=0;
 $('#score-list').innerHTML=ranked.map((p,i)=>{if(p.points!==lastScore){rank=i+1;lastScore=p.points;}return`<li class="score-row"><span class="score-rank">${rank}</span>${avatar(p)}<div class="score-person"><strong>${escape(p.name)}</strong><small>${escape(p.nickname||characters[p.avatar].name)}</small></div><span class="score-points">${p.points}<small>pts</small></span></li>`;}).join('');
 $('#score-empty').hidden=!!ranked.length;$('#points-total').textContent=`${state.ledger.reduce((n,e)=>n+e.points,0)} points awarded`;$('#undo-score').disabled=!state.ledger.length;
}
function guide(){openModal(`<div class="dialog-pad"><p class="eyebrow green">THE HOST’S LITTLE HELPER</p><h2 id="dialog-title">A meeting worth unmuting for.</h2><ol class="guide-steps"><li><strong>Build your line-up.</strong><span>Add people or teams and pick their festive avatars. Personal photos are optional.</span></li><li><strong>Share this window in Teams.</strong><span>Keep one person in charge of the site. Players answer aloud or in Teams chat; they do not need to open the site.</span></li><li><strong>Pick a round and start the timer.</strong><span>Quiz and emoji answers stay hidden until you reveal them. The host decides when to move on.</span></li><li><strong>Award points fairly.</strong><span>1 point for correct quiz and emoji answers. Up to 3 points for the dash and sales pitch. Rotate turns in the timed challenges.</span></li><li><strong>Crown your winner.</strong><span>Tied scores share first place. Use Undo or Adjust scores to fix mistakes.</span></li></ol><div class="notice"><strong>Before the meeting:</strong> run a practice round, then reset scores. Download a backup. Scores are saved only in this browser — there is no live multiplayer sync. Budget roughly 30–40 minutes for all four rounds.</div><button class="button button-green" id="guide-ready">Let’s get festive →</button></div>`);$('#guide-ready').onclick=closeModal;}
function editPlayer(id=null,preset=0){
 const p=state.players.find(x=>x.id===id)||{name:'',nickname:'',avatar:preset,photo:null};photoDraft=p.photo||null;
 openModal(`<form id="player-form" class="dialog-pad"><p class="eyebrow green">THE AVATAR WORKSHOP</p><h2 id="dialog-title">${id?'Refine your festive alter ego.':'Unleash your inner elf.'}</h2><div class="form-row"><label class="field">Player or team name<input id="player-name" value="${escape(p.name)}" placeholder="e.g. Jack / The Trim Reapers" maxlength="60" required></label><label class="field">Festive nickname <span>(optional)</span><input id="player-nickname" value="${escape(p.nickname)}" placeholder="e.g. Chief Mince Pie Officer" maxlength="60"></label></div><fieldset class="avatar-picker"><legend>Choose your Christmas character</legend>${characters.map((c,i)=>`<label class="avatar-choice" title="${c.name}"><input type="radio" name="avatar" value="${i}" ${p.avatar===i?'checked':''} aria-label="${c.name}"><span class="avatar face-${i}" aria-hidden="true"></span></label>`).join('')}</fieldset><label class="field">Or use a personal avatar / photo<input id="photo-upload" type="file" accept="image/png,image/jpeg,image/webp"></label><div id="photo-area">${photoDraft?`<img class="photo-preview" src="${escape(photoDraft)}" alt="Current player avatar"><button type="button" class="text-button" id="remove-photo">Use the Christmas character instead</button>`:''}</div><p>These are ready-made festive characters. You can upload a finished personal caricature or a photo here. Photos stay on this device and are included in backups.</p><div class="dialog-actions">${id?'<button type="button" class="text-button danger" id="delete-player">Remove player</button>':''}<button class="button button-green" type="submit">${id?'Save changes':'Add to the line-up'} →</button></div></form>`);
 const wireRemove=()=>{if($('#remove-photo'))$('#remove-photo').onclick=()=>{photoDraft=null;$('#photo-area').innerHTML='';$('#photo-upload').value='';};};wireRemove();
 $('#photo-upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;const saveButton=$('#player-form button[type=submit]');saveButton.disabled=true;try{photoDraft=await readPhoto(file);if(!$('#photo-area'))return;$('#photo-area').innerHTML=`<img class="photo-preview" src="${escape(photoDraft)}" alt="Selected avatar"><button type="button" class="text-button" id="remove-photo">Use the Christmas character instead</button>`;wireRemove();}catch(err){notify(err.message);e.target.value='';}finally{saveButton.disabled=false;}};
 $('#player-form').onsubmit=e=>{e.preventDefault();const name=$('#player-name').value.trim();if(!name)return notify('Add a name first.');if(state.players.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))return notify('That name is already in the line-up. Add a surname or team number.');if(!id&&state.players.length>=60)return notify('The line-up supports up to 60 players or teams.');const next={id:id||crypto.randomUUID(),name,nickname:$('#player-nickname').value.trim(),avatar:Number($('input[name=avatar]:checked').value),photo:photoDraft};if(id)state.players=state.players.map(x=>x.id===id?next:x);else state.players.push(next);save();closeModal();notify(`${name} is on the nice list.`);};
 if(id)$('#delete-player').onclick=()=>{if(!confirm(`Remove ${p.name} and their points? This cannot be undone.`))return;state.players=state.players.filter(x=>x.id!==id);state.ledger=state.ledger.filter(x=>x.playerId!==id);save();closeModal();};
}
async function readPhoto(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Choose a PNG, JPG or WebP image.');if(file.size>8*1024*1024)throw new Error('Choose an image smaller than 8 MB.');const bitmap=await createImageBitmap(file);try{const canvas=document.createElement('canvas');canvas.width=300;canvas.height=300;const ctx=canvas.getContext('2d');const side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,300,300);return canvas.toDataURL('image/jpeg',.85);}finally{bitmap.close();}}
function launch(id){const g=games.find(x=>x.id===id);if(!g)return;openModal(`<div class="dialog-pad"><p class="eyebrow green">${g.label} / ${g.minutes.toUpperCase()}</p><h2 id="dialog-title">${g.name}</h2><p>${g.instructions}</p><div class="notice"><strong>${g.meta}.</strong><br>${g.id==='quiz'||g.id==='emoji'?'Everyone locks in their answer before the reveal. Each correct player or team can score.':'Give each player or team a similar number of turns. More players than cards? Play in teams.'}</div>${!state.players.length?'<p>Add at least one player or team before you start scoring.</p>':''}<div class="dialog-actions"><button class="button button-green" id="start-game">${state.players.length?'Start / resume round →':'Add your first player →'}</button></div></div>`);$('#start-game').onclick=()=>{if(!state.players.length)return editPlayer();activeGame=g;dialog.classList.add('game-dialog');if(!state.progress[id])state.progress[id]={index:0,revealed:false};remaining=g.seconds;save();renderRound();};}
function stopTimer(){clearInterval(timerHandle);timerHandle=null;deadline=null;}
function timerUpdate(){if(!deadline)return;remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));const el=$('#timer');if(el){el.textContent=`0:${String(remaining).padStart(2,'0')}`;el.classList.toggle('expired',remaining===0);}if(remaining===0){stopTimer();if($('#toggle-timer'))$('#toggle-timer').textContent='Time’s up';notify('Time’s up! Finish your answer.');}}
function toggleTimer(){if(timerHandle){timerUpdate();stopTimer();if($('#toggle-timer'))$('#toggle-timer').textContent='Resume';return;}if(remaining<=0)return;deadline=Date.now()+remaining*1000;timerHandle=setInterval(timerUpdate,200);$('#toggle-timer').textContent='Pause';timerUpdate();}
function renderRound(){
 const g=activeGame;if(!g)return;const p=state.progress[g.id];if(p.index>=g.cards.length)return finishRound(g);
 const c=g.cards[p.index],scorable=p.revealed||g.maxPoints>1,key=`${g.id}:${p.index}`;
 $('#dialog-content').innerHTML=`<div class="round-header"><p class="eyebrow green">PROFILPAS 2026 CHRISTMAS GAMES</p><h2 id="dialog-title">${g.name}</h2></div><div class="round-layout"><div class="round-progress"><span style="width:${p.index/g.cards.length*100}%"></span></div><div class="round-meta"><span>CARD ${p.index+1} OF ${g.cards.length}${c.category?' · '+c.category.toUpperCase():''}</span><div class="timer-controls"><span class="timer ${remaining===0?'expired':''}" id="timer" role="timer" aria-label="Seconds remaining">0:${String(remaining).padStart(2,'0')}</span><button id="toggle-timer">${timerHandle?'Pause':remaining===0?'Time’s up':'Start timer'}</button><button id="reset-timer" aria-label="Reset timer">↶</button></div></div><div class="question ${g.id==='emoji'?'emoji-question':''}">${c.q}</div>${g.id==='quiz'?`<div class="answer-options">${c.options.map((o,i)=>`<div class="answer-option ${p.revealed?(i===c.answer?'correct':'dim'):''}"><b>${String.fromCharCode(65+i)}</b>${o}${p.revealed&&i===c.answer?' ✓':''}</div>`).join('')}</div>`:''}${g.id==='pitch'?`<div class="pitch-card"><span aria-hidden="true">🎅</span><p>${c.note}</p></div>`:''}${g.maxPoints===1?(p.revealed?`<div class="reveal-box"><strong>${g.id==='quiz'?c.options[c.answer]:c.answer}</strong>${c.note}</div>`:'<div class="reveal-action"><button class="button button-green" id="reveal-answer">Reveal the answer ✦</button></div>'):`<p class="round-instructions">${g.id==='list'?'Five valid answers = 3 pts · Three or four = 2 pts · One or two = 1 pt':'1 for completing it · 1 for creativity · 1 for making the room laugh'}</p>`}<div class="award-area"><p>${scorable?g.maxPoints===1?'Who got it right? Award 1 point to each correct player or team.':'Award points to the player or team who took this turn.':'Keep answers hidden until everyone has answered.'}</p>${scorable?`<div class="award-buttons">${state.players.map(x=>{const done=state.ledger.some(e=>e.playerId===x.id&&e.key===key);return`<button class="award-button" data-award="${escape(x.id)}" ${done?'disabled':''}>${avatar(x)} ${escape(x.name)} ${done?'✓':g.maxPoints===1?'+1':'+'}</button>`;}).join('')}</div>`:''}</div></div><div class="round-footer"><button class="text-button" id="end-round">Save & exit</button><button class="button button-green" id="next-card">${p.index===g.cards.length-1?'Finish round':'Next card'} →</button></div>`;
 $('#toggle-timer').onclick=toggleTimer;$('#reset-timer').onclick=()=>{stopTimer();remaining=g.seconds;renderRound();};if($('#reveal-answer'))$('#reveal-answer').onclick=()=>{stopTimer();p.revealed=true;save();renderRound();};$('#end-round').onclick=closeModal;
 $('#next-card').onclick=()=>{if(g.maxPoints===1&&!p.revealed&&!confirm('Skip this card without revealing or awarding points?'))return;stopTimer();p.index++;p.revealed=false;remaining=g.seconds;save();renderRound();render();};
 $$('[data-award]').forEach(b=>b.onclick=()=>{let points=1;if(g.maxPoints>1){const answer=prompt('Award 1, 2 or 3 points. Cancel to leave unchanged.','3');if(answer===null)return;points=Number(answer);if(!Number.isInteger(points)||points<1||points>3)return notify('Choose 1, 2 or 3 points.');}try{award(state,{playerId:b.dataset.award,points,source:`${g.short} · card ${p.index+1}`,key});save();render();renderRound();notify(`+${points} ${points===1?'point':'points'} awarded.`);}catch(err){notify(err.message);}});
}
function finishRound(g){stopTimer();$('#dialog-content').innerHTML=`<div class="dialog-pad winner"><div class="finish-icon" aria-hidden="true">🎁</div><p class="eyebrow green">THAT’S A WRAP</p><h2 id="dialog-title">${g.short}: complete.</h2><p>Good answers. Better banter. Time for the next round?</p><div class="notice">${state.ledger.filter(e=>e.key?.startsWith(g.id+':')).reduce((n,e)=>n+e.points,0)} points awarded in this round.</div><button class="button button-green" id="back-games">Back to the games →</button><p><button class="text-button" id="replay-game">Replay this round</button></p></div>`;$('#back-games').onclick=closeModal;$('#replay-game').onclick=()=>{if(!confirm('Replay this round? This clears only the scores from this round.'))return;state.ledger=state.ledger.filter(e=>!e.key?.startsWith(g.id+':'));state.progress[g.id]={index:0,revealed:false};remaining=g.seconds;save();render();renderRound();};}
function adjustScores(){if(!state.players.length)return editPlayer();openModal(`<form class="dialog-pad" id="adjust-form"><p class="eyebrow green">THE HOST’S DECISION</p><h2 id="dialog-title">Keep the scores straight.</h2><label class="field">Player / team<select id="adjust-player">${state.players.map(p=>`<option value="${escape(p.id)}">${escape(p.name)}</option>`).join('')}</select></label><div class="form-row"><label class="field">Points to add or remove<input id="adjust-points" type="number" value="1" min="-100" max="100" step="1" required></label><label class="field">Reason<input id="adjust-reason" maxlength="100" placeholder="e.g. Tie-break bonus" required></label></div><button class="button button-green" type="submit">Apply adjustment</button><h3>Recent scores</h3><ul class="score-history">${state.ledger.slice(-10).reverse().map(e=>`<li><span>${escape(state.players.find(p=>p.id===e.playerId)?.name||'Player')} · ${escape(e.source)}</span><strong>${e.points>0?'+':''}${e.points}</strong></li>`).join('')||'<li>No scores yet.</li>'}</ul></form>`);$('#adjust-form').onsubmit=e=>{e.preventDefault();try{award(state,{playerId:$('#adjust-player').value,points:Number($('#adjust-points').value),source:$('#adjust-reason').value.trim()||'Host adjustment'});save();closeModal();notify('Score updated.');}catch(err){notify(err.message);}};}
function winner(){const ranked=leaderboard(state);if(!ranked.length||!state.ledger.length)return notify('Play a round and award some points first.');const winners=ranked.filter(p=>p.points===ranked[0].points);openModal(`<div class="dialog-pad winner"><p class="eyebrow green">PROFILPAS 2026 CHRISTMAS GAMES</p><div class="finish-icon" aria-hidden="true">🏆</div><h2 id="dialog-title">${winners.length>1?'Our joint Christmas champions!':'Our Christmas champion!'}</h2><div>${winners.map(p=>`<div>${avatar(p)}<h3>${escape(p.name)}</h3></div>`).join('')}</div><p><strong>${ranked[0].points} points.</strong> A truly festive finish.</p><p>Bragging rights valid until further notice.</p><button class="button button-green" id="winner-done">Back to the celebrations</button></div>`);$('#winner-done').onclick=closeModal;celebrate();}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const layer=$('#confetti');layer.replaceChildren();for(let i=0;i<60;i++){const e=document.createElement('i');e.className='confetti-bit';e.style.left=`${Math.random()*100}%`;e.style.background=['#edcf93','#0ca337','#a53339','#fffdf5'][i%4];e.style.animationDelay=`${Math.random()*.8}s`;layer.append(e);}setTimeout(()=>layer.replaceChildren(),3700);}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`profilpas-christmas-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup downloaded. Keep it somewhere safe.');}
$('#backup-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>25*1024*1024)throw new Error('Backup is too large. Maximum 25 MB.');const next=validateBackup(JSON.parse(await file.text()));if(!confirm(`Restore ${next.players.length} players and ${next.ledger.length} score entries? This replaces this browser’s current game.`))return;state=next;save();render();notify('Backup restored.');}catch(err){notify(err instanceof SyntaxError?'That file is not a valid JSON backup.':err.message);}finally{e.target.value='';}};
$('#host-guide').onclick=guide;$('#how-to-play').onclick=guide;$('#hero-add').onclick=()=>{$('#team').scrollIntoView({behavior:'smooth'});if(!state.players.length)editPlayer();};$('#add-player').onclick=()=>editPlayer();$('#board-add').onclick=()=>editPlayer();$('#manual-score').onclick=adjustScores;$('#show-winner').onclick=winner;$('#export-data').onclick=exportData;$('#import-data').onclick=()=>$('#backup-file').click();
$('#undo-score').onclick=()=>{const e=state.ledger.at(-1);if(!e)return;if(!confirm(`Undo ${e.points>0?'+':''}${e.points} points for ${state.players.find(p=>p.id===e.playerId)?.name}?`))return;state.ledger.pop();save();render();notify('Last score undone.');};
$('#reset-scores').onclick=()=>{if(!confirm('Reset every score and restart all four rounds? Your player line-up and avatars will stay. Download a backup first if you want to keep the results.'))return;state.ledger=[];state.progress={};save();render();notify('Fresh scores. Fresh bragging rights.');};
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY&&e.newValue){try{const next=validateBackup(JSON.parse(e.newValue));if(dialog.open)closeModal();state=next;render();notify('Loaded the latest game from your other tab. Please host from one tab at a time.');}catch{notify('Could not load changes from another tab.');}}});
render();if(loadError)notify('Saved game could not be loaded. Restore a backup if you have one.');
